"""Initiative vectors of the companion contract (docs/COMPANION-CONTRACT.md), generated by MOSAIC's own initiative().

MOSAIC is read-only from this repository: its companion module is loaded by file path (its package __init__ is not run)
and no bytecode is written. Run with the MOSAIC checkout's file and this folder's vectors file:

    python3 -B -I configs/companion/generate_initiative_vectors.py \
        <MOSAIC>/ai-python/mosaic/integration/companion.py configs/companion/initiative-vectors.json

The cases cover every gate and both sides of the threshold; the file records the source file's SHA-256 and the date read.
"""
import hashlib, importlib.util, json, sys, time
sys.dont_write_bytecode = True
src = sys.argv[1]; out = sys.argv[2]
spec = importlib.util.spec_from_file_location("mosaic_companion_readonly", src)
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
NOW = 1_000_000.0
def u(ago, text): return dict(created=NOW - ago, input=text, kind="chat")
def p(ago): return dict(created=NOW - ago, input="", kind="proactive")
cases = [
  ("no user turns yet", [], 14),
  ("night hours", [u(900, "今天面试，有点紧张")], 2),
  ("asked for quiet within two hours", [u(900, "安静点，我要看书")], 14),
  ("quiet request older than two hours", [u(7300, "安静点")], 14),
  ("last words were leaving", [u(900, "我去洗澡了，待会聊")], 14),
  ("leaving words are case-insensitive", [u(900, "Good night!")], 14),
  ("two of her lines unanswered", [p(400), p(900), u(1500, "今天面试，有点紧张")], 14),
  ("not quiet long enough", [u(120, "今天面试，有点紧张")], 14),
  ("one line unanswered doubles the quiet minimum", [p(300), u(900, "今天面试，有点紧张")], 14),
  ("she spoke first recently", [u(250, "还行吧，挺顺利的"), p(300)], 14),
  ("hourly budget used", [u(500, "嗯嗯，晚点再说这个"), p(600), u(1200, "好的"), p(1300), u(2000, "哈哈"), p(2100)], 14),
  ("worth following up, about five and a half minutes", [u(330, "今天面试，有点紧张")], 14),
  ("short reply is not worth following up", [u(330, "嗯")], 14),
  ("short reply, ten minutes of quiet", [u(600, "嗯")], 14),
  ("follow-up older than two hours", [u(10800, "今天面试，有点紧张")], 14),
  ("one answered line this hour lowers the score", [u(360, "还挺好的，谢谢你问"), p(1200)], 14),
  ("one answered line this hour, longer quiet", [u(560, "还挺好的，谢谢你问"), p(1400)], 14),
  ("night window ends at seven", [u(900, "今天面试，有点紧张")], 7),
]
vectors = []
for name, turns, hour in cases:
    r = m.initiative(turns, NOW, hour)
    vectors.append(dict(name=name, now=NOW, hour=hour, turns=turns,
                        expected=dict(speak=r["speak"], score=r["score"], reason=r["reason"], followUp=r["follow_up"],
                                      parts=r["parts"])))
data = open(src, "rb").read()
doc = dict(source=dict(file="ai-python/mosaic/integration/companion.py (MOSAIC working copy)", function="initiative",
                       sha256=hashlib.sha256(data).hexdigest(), readOn=sys.argv[3] if len(sys.argv) > 3 else time.strftime("%Y-%m-%d")),
           params=m.INITIATIVE, leaving=list(m.LEAVING), hush=list(m.HUSH), vectors=vectors)
json.dump(doc, open(out, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
for v in vectors: print(f"{v['name'][:48]:48s} speak={v['expected']['speak']!s:5s} score={v['expected']['score']} reason={v['expected']['reason']}")
